'use client';
import { useState } from 'react';
import { useAuth } from '@/context/AuthContext';
import { Power, MapPin, DollarSign, Clock } from 'lucide-react';

export default function DashboardPage() {
    const { user } = useAuth();
    const [isOnline, setIsOnline] = useState(false);

    return (
        <div className="p-4 space-y-6">
            <header className="flex justify-between items-center">
                <div>
                    <h1 className="text-xl font-bold text-gray-900">Hello, {user?.email?.split('@')[0] || 'Partner'}!</h1>
                    <p className="text-sm text-gray-500">Ready to deliver today?</p>
                </div>
                <button
                    onClick={() => setIsOnline(!isOnline)}
                    className={`px-4 py-2 rounded-full font-bold text-sm flex items-center gap-2 transition-all ${isOnline ? 'bg-green-500 text-white shadow-lg shadow-green-200' : 'bg-gray-200 text-gray-600'
                        }`}
                >
                    <Power size={16} />
                    {isOnline ? 'ONLINE' : 'OFFLINE'}
                </button>
            </header>

            {/* Stats Cards */}
            <div className="grid grid-cols-2 gap-4">
                <div className="bg-orange-50 p-4 rounded-xl border border-orange-100">
                    <div className="flex items-center gap-2 mb-2 text-orange-600">
                        <DollarSign size={18} />
                        <span className="text-xs font-bold uppercase">Earnings</span>
                    </div>
                    <p className="text-2xl font-bold text-gray-900">₹450</p>
                    <p className="text-xs text-gray-500 mt-1">Today</p>
                </div>

                <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                    <div className="flex items-center gap-2 mb-2 text-blue-600">
                        <Clock size={18} />
                        <span className="text-xs font-bold uppercase">Hours</span>
                    </div>
                    <p className="text-2xl font-bold text-gray-900">3.5</p>
                    <p className="text-xs text-gray-500 mt-1">Online</p>
                </div>
            </div>

            {/* Active Order or Waiting State */}
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 min-h-[200px] flex flex-col items-center justify-center p-6 text-center">
                {isOnline ? (
                    <>
                        <div className="w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center mb-4 animate-pulse">
                            <MapPin size={32} className="text-primary" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900">Finding Orders...</h3>
                        <p className="text-sm text-gray-500 mt-2 max-w-[200px]">
                            Stay in high demand areas to get more orders.
                        </p>
                    </>
                ) : (
                    <>
                        <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mb-4">
                            <Power size={32} className="text-gray-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900">You are Offline</h3>
                        <p className="text-sm text-gray-500 mt-2 max-w-[200px]">
                            Go online to start receiving delivery requests.
                        </p>
                    </>
                )}
            </div>

            {/* Recent Activity */}
            <div>
                <h3 className="font-bold text-gray-900 mb-3">Recent Activity</h3>
                <div className="space-y-3">
                    {[1, 2].map((i) => (
                        <div key={i} className="flex justify-between items-center p-3 bg-white border border-gray-100 rounded-xl">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-green-50 rounded-full flex items-center justify-center text-green-600 font-bold text-xs">
                                    ₹45
                                </div>
                                <div>
                                    <p className="font-semibold text-sm text-gray-900">Order #882{i}</p>
                                    <p className="text-xs text-gray-500">Delivered • 2:30 PM</p>
                                </div>
                            </div>
                            <span className="text-xs font-medium bg-gray-100 px-2 py-1 rounded text-gray-600">Cash</span>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}
